from palette.css import render_css


def test_plain_name():
    assert render_css({"ink": "#000"}) == ":root {\n  --ink: #000;\n}\n"


def test_renderer_rewrites_underscores():
    assert render_css({"soft_blue": "#abc"}) == ":root {\n  --soft-blue: #abc;\n}\n"


